"use client";

import { motion } from "framer-motion";
import { useSwarmStore } from "@/lib/store";
import { GlassCard } from "@/components/ui/GlassCard";
import { Button } from "@/components/ui/Button";
import { AnimatedCounter } from "@/components/ui/AnimatedCounter";
import { parseMoneyToNumber, formatCompactCurrency } from "@/lib/parseMoney";

const container = {
  hidden: {},
  show: { transition: { staggerChildren: 0.12 } },
};

const item = {
  hidden: { opacity: 0, y: 18 },
  show: { opacity: 1, y: 0, transition: { duration: 0.5, ease: "easeOut" as const } },
};

function StatCard({ label, raw }: { label: string; raw?: string }) {
  const parsed = parseMoneyToNumber(raw);
  return (
    <motion.div variants={item} className="glass-panel rounded-xl p-4">
      <p className="text-xs uppercase tracking-wide text-muted">{label}</p>
      {parsed !== null ? (
        <AnimatedCounter
          target={parsed}
          formatter={formatCompactCurrency}
          className="mt-1 block text-2xl font-bold glow-text"
        />
      ) : (
        <p className="mt-1 text-2xl font-bold text-foreground/70">{raw || "—"}</p>
      )}
    </motion.div>
  );
}

export default function ResultsScreen() {
  const result = useSwarmStore((s) => s.result);
  const idea = useSwarmStore((s) => s.idea);
  const reset = useSwarmStore((s) => s.reset);

  const cmo = result?.cmo_output;
  const cto = result?.cto_output;
  const cfo = result?.cfo_output;
  const score = result?.investor_score;

  return (
    <motion.div
      variants={container}
      initial="hidden"
      animate="show"
      className="mx-auto flex h-full w-full max-w-5xl flex-col gap-6 overflow-y-auto p-6"
    >
      <motion.div variants={item} className="flex items-start justify-between gap-4">
        <div>
          <p className="text-xs font-semibold uppercase tracking-[0.2em] text-accent">Pitch ready</p>
          <h1 className="mt-1 text-2xl font-bold sm:text-3xl">{idea}</h1>
          {result?.ceo_narrative && <p className="mt-2 max-w-2xl text-sm text-muted">{result.ceo_narrative}</p>}
        </div>
        <Button variant="ghost" onClick={reset}>
          Start over
        </Button>
      </motion.div>

      {cto?.landing_page_html && (
        <motion.div variants={item}>
          <GlassCard className="overflow-hidden p-0">
            <div className="flex items-center gap-1.5 border-b border-border px-4 py-2.5">
              <span className="h-2.5 w-2.5 rounded-full bg-red-400/70" />
              <span className="h-2.5 w-2.5 rounded-full bg-yellow-400/70" />
              <span className="h-2.5 w-2.5 rounded-full bg-emerald-400/70" />
              <span className="ml-3 text-xs text-muted">Landing page preview</span>
            </div>
            <iframe
              title="Generated landing page"
              srcDoc={cto.landing_page_html}
              className="h-[420px] w-full bg-white"
              sandbox=""
            />
          </GlassCard>
        </motion.div>
      )}

      <div className="grid grid-cols-2 gap-4 sm:grid-cols-4">
        <StatCard label="Funding ask" raw={cfo?.funding_ask?.amount} />
        <StatCard label="TAM" raw={cmo?.market?.tam} />
        <StatCard label="Dev cost" raw={cfo?.cost_projection?.development_cost} />
        <motion.div variants={item} className="glass-panel rounded-xl p-4">
          <p className="text-xs uppercase tracking-wide text-muted">Investor score</p>
          {typeof score === "number" ? (
            <AnimatedCounter target={score} className="mt-1 block text-2xl font-bold glow-text" />
          ) : (
            <p className="mt-1 text-2xl font-bold text-foreground/70">—</p>
          )}
          <span className="text-xs text-muted">/ 10</span>
        </motion.div>
      </div>

      {(cfo?.unit_economics || cfo?.revenue_model_options) && (
        <motion.div variants={item} className="grid gap-4 sm:grid-cols-2">
          <GlassCard className="p-5">
            <p className="mb-2 text-xs font-semibold uppercase tracking-wide text-accent">Unit economics</p>
            <dl className="space-y-1 text-sm">
              <div className="flex justify-between"><dt className="text-muted">CAC</dt><dd>{cfo?.unit_economics?.cac || "—"}</dd></div>
              <div className="flex justify-between"><dt className="text-muted">LTV</dt><dd>{cfo?.unit_economics?.ltv || "—"}</dd></div>
              <div className="flex justify-between"><dt className="text-muted">Gross margin</dt><dd>{cfo?.unit_economics?.gross_margin || "—"}</dd></div>
            </dl>
          </GlassCard>
          <GlassCard className="p-5">
            <p className="mb-2 text-xs font-semibold uppercase tracking-wide text-accent">Revenue models</p>
            <ul className="space-y-2 text-sm">
              {cfo?.revenue_model_options?.map((r, i) => (
                <li key={i}>
                  <span className="font-semibold">{r.model}</span>
                  <span className="text-muted"> — {r.description}</span>
                </li>
              ))}
            </ul>
          </GlassCard>
        </motion.div>
      )}

      {result?.investor_transcript && result.investor_transcript.length > 0 && (
        <motion.div variants={item}>
          <GlassCard className="p-5">
            <p className="mb-3 text-xs font-semibold uppercase tracking-wide text-accent">
              Investor Q&amp;A transcript
            </p>
            <div className="space-y-4">
              {result.investor_transcript.map((entry, i) => (
                <motion.div
                  key={i}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ duration: 0.4, delay: i * 0.08 }}
                  className="border-l-2 border-primary/40 pl-4 text-sm"
                >
                  <p className="font-semibold text-foreground/90">Q: {entry.q}</p>
                  <p className="mt-1 text-muted">A: {entry.a}</p>
                  {entry.rebuttal && (
                    <>
                      <p className="mt-2 text-amber-300/90">Investor pushback: {entry.rebuttal}</p>
                      <p className="mt-1 text-muted">CEO defense: {entry.defense}</p>
                    </>
                  )}
                </motion.div>
              ))}
            </div>
          </GlassCard>
        </motion.div>
      )}
    </motion.div>
  );
}
