// Mirrors backend/tools/idea_classifier.py's CATEGORY_KEYWORDS keys exactly.
export type Category = "saas" | "marketplace" | "mobile_app" | "consumer";

export const CATEGORIES: { value: Category; label: string; blurb: string }[] = [
  { value: "saas", label: "SaaS", blurb: "B2B platform, dashboard, workflow tool" },
  { value: "marketplace", label: "Marketplace", blurb: "Buyers + sellers, listings, bookings" },
  { value: "mobile_app", label: "Mobile App", blurb: "On-the-go, tracker, notifications" },
  { value: "consumer", label: "Consumer Product", blurb: "Subscription box, D2C, lifestyle" },
];

export type AgentId = "ceo" | "cmo" | "cto" | "cfo" | "investor";
export type AgentStatusValue = "idle" | "active" | "done" | "error";

export interface AgentStatus {
  id: AgentId;
  label: string;
  status: AgentStatusValue;
}

export interface LogLine {
  id: string;
  text: string;
}

// SSE payloads emitted by backend/api/main.py's /run/stream endpoint.
export type PipelineEvent =
  | { type: "start"; message: string }
  | { type: "node_complete"; node: string; label: string; data: Record<string, unknown> }
  | { type: "error"; message: string }
  | { type: "done" };

// Loosely typed — each field is whatever the corresponding LangGraph node returned
// (backend/agents/schemas.py::CTOOutput / CFOOutput shapes for cto_output / cfo_output).
export interface PipelineResult {
  status?: string;
  cmo_output?: {
    market?: { tam?: string; sam?: string; som?: string; reasoning?: string };
    competitors?: { name: string; summary: string }[];
    persona?: { name?: string; age_range?: string; occupation?: string; pain_points?: string[] };
    gtm_strategy?: string;
  };
  cto_output?: {
    category?: string;
    mvp_features?: { name: string; description: string; priority: string }[];
    tech_stack?: { frontend?: string; backend?: string; database?: string; hosting?: string; rationale?: string };
    architecture_summary?: string;
    landing_page_html?: string;
  };
  cfo_output?: {
    category?: string;
    cost_projection?: { development_cost?: string; operational_cost?: string; reasoning?: string };
    revenue_model_options?: { model: string; description: string }[];
    unit_economics?: { cac?: string; ltv?: string; gross_margin?: string; reasoning?: string };
    funding_ask?: { amount?: string; use_of_funds?: string; reasoning?: string };
  };
  ceo_narrative?: string;
  investor_transcript?: { q: string; a: string; rebuttal?: string; defense?: string }[];
  investor_score?: number;
}
