import { create } from "zustand";
import { streamPipeline } from "./api";
import type { AgentId, AgentStatus, Category, LogLine, PipelineEvent, PipelineResult } from "./types";

export const AGENT_ORDER: AgentId[] = ["ceo", "cmo", "cto", "cfo", "investor"];

const AGENT_LABELS: Record<AgentId, string> = {
  ceo: "CEO",
  cmo: "CMO",
  cto: "CTO",
  cfo: "CFO",
  investor: "Investor",
};

// Maps LangGraph node names (backend/orchestration/graph.py) to the 5 conceptual agents
// the 3D scene visualizes. CEO fires 3x (parse, synthesize, answer_questions) and Investor
// fires 2x (select_questions, score_pitch) — both just re-flash "done" each time, which
// reads fine visually.
const NODE_TO_AGENT: Record<string, AgentId> = {
  parse_idea: "ceo",
  cmo: "cmo",
  cto: "cto",
  cfo: "cfo",
  synthesize: "ceo",
  select_questions: "investor",
  answer_questions: "ceo",
  score_pitch: "investor",
};

const NODE_LOG_LABELS: Record<string, string> = {
  parse_idea: "CEO-agent: idea parsed",
  cmo: "CMO-agent: market sizing + competitor scan complete",
  cto: "CTO-agent: MVP spec + landing page generated",
  cfo: "CFO-agent: financial projection complete",
  synthesize: "CEO-agent: pitch narrative synthesized",
  select_questions: "Investor-agent: questions selected",
  answer_questions: "CEO-agent: investor Q&A complete",
  score_pitch: "Investor-agent: pitch scored",
};

// No explicit "node started" events come from the backend (LangGraph's stream_mode
// "updates" only yields on completion) — so when a node completes, we eagerly mark
// whatever runs next as "active" for continuous-feeling progress instead of idle -> done jumps.
const NEXT_NODES: Record<string, string[]> = {
  parse_idea: ["cmo"],
  cmo: ["cto", "cfo"],
  cto: [],
  cfo: ["synthesize"],
  synthesize: ["select_questions"],
  select_questions: ["answer_questions"],
  answer_questions: ["score_pitch"],
  score_pitch: [],
};

function initialAgents(): Record<AgentId, AgentStatus> {
  return Object.fromEntries(
    AGENT_ORDER.map((id) => [id, { id, label: AGENT_LABELS[id], status: "idle" as const }])
  ) as Record<AgentId, AgentStatus>;
}

type Screen = "hero" | "working" | "results";

interface PipelineState {
  screen: Screen;
  idea: string;
  category: Category;
  agents: Record<AgentId, AgentStatus>;
  logs: LogLine[];
  result: PipelineResult | null;
  error: string | null;
  setIdea: (idea: string) => void;
  setCategory: (category: Category) => void;
  startRun: () => void;
  reset: () => void;
}

let stopStream: (() => void) | null = null;

export const useSwarmStore = create<PipelineState>((set, get) => ({
  screen: "hero",
  idea: "",
  category: "saas",
  agents: initialAgents(),
  logs: [],
  result: null,
  error: null,

  setIdea: (idea) => set({ idea }),
  setCategory: (category) => set({ category }),

  reset: () => {
    stopStream?.();
    stopStream = null;
    set({ screen: "hero", agents: initialAgents(), logs: [], result: null, error: null });
  },

  startRun: () => {
    const { idea, category } = get();
    if (!idea.trim()) return;

    stopStream?.();
    set({
      screen: "working",
      agents: { ...initialAgents(), ceo: { id: "ceo", label: AGENT_LABELS.ceo, status: "active" } },
      logs: [{ id: "start", text: "CEO-agent: parsing your idea…" }],
      result: null,
      error: null,
    });

    stopStream = streamPipeline(idea, category, {
      onEvent: (evt: PipelineEvent) => {
        if (evt.type !== "node_complete") return;
        const doneAgent = NODE_TO_AGENT[evt.node];
        const nextAgents = (NEXT_NODES[evt.node] ?? []).map((n) => NODE_TO_AGENT[n]).filter(Boolean);
        const logText = NODE_LOG_LABELS[evt.node] ?? `${evt.node} complete`;

        set((s) => {
          const agents = { ...s.agents };
          if (doneAgent) agents[doneAgent] = { ...agents[doneAgent], status: "done" };
          for (const id of nextAgents) {
            if (agents[id].status !== "done") agents[id] = { ...agents[id], status: "active" };
          }
          return {
            agents,
            logs: [...s.logs, { id: `${evt.node}-${s.logs.length}`, text: logText }],
            result: { ...(s.result ?? {}), ...evt.data },
          };
        });
      },
      onError: (message) => set({ error: message }),
      onDone: () => set({ screen: "results" }),
    });
  },
}));
